// Watch Face Format (WFF v4) watch face - resources only, no code.
// The res/raw/watchface.xml file is GENERATED by ../../generator/gen_watchface.py;
// edit the generator, not the XML.
plugins {
    alias(libs.plugins.android.application)
}

android {
    enableKotlin = false
    namespace = "com.noorface.prayer"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.noorface.prayer"
        minSdk = 36          // WFF v4 = Wear OS 6 (One UI 8 Watch)
        targetSdk = 36
        versionCode = 7
        versionName = "1.3.2"
    }

    signingConfigs {
        create("release") {
            storeFile = file("../../signing/noor-release.jks")
            storePassword = System.getenv("NOOR_KS_PASS") ?: "noorwatchface"
            keyAlias = "noor"
            keyPassword = System.getenv("NOOR_KS_PASS") ?: "noorwatchface"
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = false   // keep every resource referenced from the WFF XML
            signingConfig = signingConfigs.getByName("release")
        }
    }
}
